<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { request, query, downloadAttachment, type Page } from '../api'
import { dateTime } from '../domain.js'
import { labels } from '../schemas'
import Modal from './Modal.vue'
import StatusBadge from './StatusBadge.vue'
import AttachmentPreview from './AttachmentPreview.vue'
const preview=ref<number|null>(null)
const kinds:Record<string,string>={merchant:'商家入驻',agency:'经纪公司入驻',broker:'销售经纪人入驻',identity:'实名认证'}
const rows=ref<any[]>([]),total=ref(0),page=ref(1),kind=ref(''),status=ref('pending'),loading=ref(false),busy=ref(false),error=ref(''),selected=ref<any>(null),decision=ref('approved'),notes=ref(''),success=ref('')
async function load(){loading.value=true;error.value='';try{const result=await request<Page>('/applications'+query({page:page.value,page_size:10,kind:kind.value,status:status.value}));rows.value=result.items;total.value=result.total}catch(err){error.value=(err as Error).message}finally{loading.value=false}}
async function submit(){if(!selected.value||busy.value)return;busy.value=true;error.value='';try{await request(`/applications/${selected.value.id}/review`,{method:'POST',body:JSON.stringify({status:decision.value,notes:notes.value})});selected.value=null;success.value='审核结果已保存；申请人的权限由服务端更新。';await load()}catch(err){error.value=(err as Error).message}finally{busy.value=false}}
async function download(id:number){try{await downloadAttachment(`/api/v1/files/${id}`,'申请材料')}catch(err){error.value=(err as Error).message}}
onMounted(load)
</script>
<template>
  <div class="page-heading"><div><h1>入驻与实名审核</h1><p>审核商家营业执照、经纪公司、销售经纪人及个人身份材料。私有材料仅授权人员可查看。</p></div></div><p v-if="error&&!selected" class="notice danger" role="alert">{{ error }}</p><p v-if="success" class="notice success" role="status">{{ success }}</p>
  <section class="panel"><form class="filter-bar" @submit.prevent="page=1;load()"><select v-model="kind" aria-label="申请类型"><option value="">全部申请</option><option v-for="(name,key) in kinds" :key="key" :value="key">{{ name }}</option></select><select v-model="status" aria-label="申请状态"><option value="">全部状态</option><option value="pending">待审核</option><option value="approved">已通过</option><option value="rejected">已驳回</option></select><button class="button">查询</button><span class="record-count">共 {{ total }} 条申请</span></form><div class="table-scroll"><table><thead><tr><th>申请编号</th><th>申请人</th><th>申请类型</th><th>组织 / 营业执照名称</th><th>状态</th><th>申请时间</th><th>操作</th></tr></thead><tbody><tr v-if="loading"><td colspan="7" class="empty">正在加载…</td></tr><tr v-else-if="!rows.length"><td colspan="7" class="empty">暂无申请</td></tr><tr v-for="row in rows" v-else :key="row.id"><td>#{{ row.id }}</td><td>用户 #{{ row.user_id }}</td><td>{{ kinds[row.kind]||row.kind }}</td><td>{{ row.payload?.legal_name||row.payload?.organization_name||'—' }}</td><td><StatusBadge :value="row.status" /></td><td>{{ dateTime(row.created_at) }}</td><td><button class="text-button" @click="selected=row;notes='';decision='approved';error=''">{{ row.status==='pending'?'查看与审核':'查看资料' }}</button></td></tr></tbody></table></div><div class="pagination"><span>第 {{ page }} 页</span><button class="button small" :disabled="page<=1||loading" @click="page--;load()">上一页</button><button class="button small" :disabled="page*10>=total||loading" @click="page++;load()">下一页</button></div></section>
  <Modal v-if="selected" :title="`${kinds[selected.kind]} #${selected.id}`" wide @close="!busy&&(selected=null)"><p v-if="error" class="notice danger" role="alert">{{ error }}</p><dl class="detail-grid"><dt>申请用户</dt><dd>#{{ selected.user_id }}</dd><dt>所属经纪公司</dt><dd>{{ selected.org_id?`#${selected.org_id}`:'—' }}</dd><dt>申请状态</dt><dd><StatusBadge :value="selected.status" /></dd><template v-for="(value,key) in selected.payload" :key="key"><dt>{{ labels[String(key)]||({organization_name:'组织名称',identity_name:'真实姓名',identity_number:'证件号码'} as Record<string,string>)[String(key)]||key }}</dt><dd>{{ typeof value==='object'?JSON.stringify(value):value }}</dd></template></dl><h3 class="section-heading">私有申请材料</h3><div v-for="(id,index) in selected.file_ids" :key="id" class="attachment-row"><span class="file-icon">FILE</span><span>申请材料 {{ Number(index)+1 }}</span><button class="text-button" @click="preview=Number(id)">预览</button><button class="text-button" @click="download(Number(id))">鉴权下载</button></div><form v-if="selected.status==='pending'" id="application-review-form" class="form-grid" style="margin-top:24px" @submit.prevent="submit"><label><span>审核结果</span><select v-model="decision"><option value="approved">审核通过</option><option value="rejected">驳回修改</option></select></label><label class="span-all"><span>审核说明 *</span><textarea v-model="notes" rows="4" required /></label></form><p v-else class="notice" style="margin-top:20px">{{ selected.review_notes||'申请已审核。' }}</p><template #footer><button class="button" :disabled="busy" @click="selected=null">关闭</button><button v-if="selected.status==='pending'" form="application-review-form" class="button primary" :disabled="busy">{{ busy?'正在提交…':'保存审核结果' }}</button></template></Modal>
<AttachmentPreview v-if="preview" :path="`/api/v1/files/${preview}`" title="私有申请材料" @close="preview=null" />
</template>
